import os
import re
from collections import UserList
from taf.internal.scf.p import P
from taf.internal.scf.tree_object import TreeListObject
from taf.internal.scf.header import Header
from taf.internal.scf.managed_object import ManagedObject
from taf.internal.scf.exceptions import ElementNotFound


class CmData(TreeListObject):
    def __init__(self, tree):
        self._tree = tree
        super().__init__(tree)

    @property
    def header(self):
        return Header(self._tree.header)

    @property
    def _path_root(self):
        try:
            return self[0]["distName"]
        except (IndexError, KeyError):
            return None

    def _get_namespace(self):
        try:
            return self._tree.nsmap[None]
        except KeyError:
            return None

    def __getattr__(self, item):
        if item.startswith("__"):
            return super().__getattr__(item)
        # create a correct distName e.g.also for "MRBTS-10191/NRBTS-1/NRDRB_5QI-3" or "SBTS-1900/RAP_RAP-1"
        item = re.sub(r"_(?=\d+$)", "-", item)
        ns = self._get_namespace()

        mo_result = self.find_single_mo(item, self._tree, ns)

        if mo_result is not None:
            return ManagedObject(mo_result)

        mos = [ManagedObject(mo) for mo in self.find_multiple_mos(item, self._tree, ns)]
        mos.sort()
        if len(mos) > 0:
            return mos

        try:
            classes = [("managedObject", ManagedObject), ("header", Header)]
            element = self.find_element(item, self._tree)
            return self.return_scf_element(element=element, classes=classes)
        except IndexError:
            raise ElementNotFound(f"Element {item} not found.")

    def elements(self):
        elements = self._tree.xpath("./node()[(@distName) and not(contains(@distName, '/'))]")
        return elements

    def __getitem__(self, item):
        try:
            return ManagedObject(self.elements()[item])
        except TypeError:  # TypeError is raised when accessing attributes of cmData
            return super().__getitem__(item)

    def __len__(self):
        return len(self.elements())

    class CmDataIterator:
        def __init__(self, cmdata):
            self._cm_data = cmdata
            self._current_index = 0

        def __next__(self):
            if self._current_index < len(self._cm_data):
                result = self._cm_data[self._current_index]
                self._current_index += 1
                return result
            else:
                self._current_index = 0
                raise StopIteration

        def next(self):
            return self.__next__()

        def __iter__(self):
            return self

    def __iter__(self):
        return CmData.CmDataIterator(self)

    def child_exists(self, dist_name):
        """Test if the managedObject with given name exists in SCF

        :param dist_name: managedObject distName to find
        :return: True if exists, False if not
        """
        ns = self._tree.nsmap[None]
        find_string = f".//{{{ns}}}managedObject[@distName='{dist_name}']"
        return self._tree.getparent().find(find_string) is not None

    def get_all_elements(self, dist_name=None, list_name=None, p_name=None):
        if dist_name:
            dist_name = self._parse_path(dist_name)
        path = self._create_xpath_path(dist_name, list_name, p_name)
        ns = self._get_namespace()
        matched_elements = self._tree.xpath(path, namespaces={"ns": ns})
        classes = [("p", P)]
        internal_elements = XPathElementsList(
            [self.return_scf_element(elem, classes) for elem in matched_elements],
            used_xpath=path,
        )
        return internal_elements

    def get_all_elements_by_pattern(self, dist_name=None, list_name=None, p_name=None):
        if dist_name:
            dist_name = self._parse_path(dist_name)
        path = self._create_xpath_path_regex(dist_name, list_name, p_name)
        ns = self._get_namespace()
        matched_elements = self._tree.xpath(
            path, namespaces={"ns": ns, "re": "http://exslt.org/regular-expressions"}
        )
        classes = [("p", P)]
        internal_elements = XPathElementsList(
            [self.return_scf_element(elem, classes) for elem in matched_elements],
            used_xpath=path,
        )
        return internal_elements

    def get_dist_names_by_class(self, mo_class):
        path = f"//ns:managedObject[@class='{mo_class}']"
        ns = self._get_namespace()
        matched_objects = self._tree.xpath(path, namespaces={"ns": ns})
        classes = [("managedObject", ManagedObject)]
        objects = XPathElementsList(
            [self.return_scf_element(elem, classes) for elem in matched_objects],
            used_xpath=path,
        )
        return objects

    def get_dist_names_by_pattern(self, pattern):
        pattern = self._parse_path(pattern)
        path = f"//ns:managedObject[re:match(@distName,'{pattern}')]"
        ns = self._get_namespace()
        matched_objects = self._tree.xpath(
            path, namespaces={"ns": ns, "re": "http://exslt.org/regular-expressions"}
        )
        classes = [("managedObject", ManagedObject)]
        objects = XPathElementsList(
            [self.return_scf_element(elem, classes) for elem in matched_objects],
            used_xpath=path,
        )
        return objects

    def _parse_path(self, path):
        """Key can contain SBTS specific information e.g. SBTS-1900/TNL-1,
        SBTS-1900 should be omitted when using keyword, because it does not
        provide additional information and can cause problem in future
        when SBTS version will be changed."""
        if self._path_root and self._path_root not in path:
            path = os.path.join(self._path_root, path)
        return path if not path.endswith("/") else path[:-1]

    @staticmethod
    def _create_xpath_path(dist_name, list_name, p_name):
        path = ""
        if dist_name is not None:
            path += f"//ns:managedObject[@distName='{dist_name}']"
        if list_name is not None:
            path += f"//ns:list[@name='{list_name}']"
        if p_name is not None:
            path += f"//ns:p[@name='{p_name}']"
        else:
            path += "//ns:p"
        return path

    @staticmethod
    def _create_xpath_path_regex(dist_name, list_name, p_name):
        path = ""
        if dist_name is not None:
            path += f"//ns:managedObject[re:match(@distName,'{dist_name}')]"
        if list_name is not None:
            path += f"//ns:list[re:match(@name,'{list_name}')]"
        if p_name is not None:
            path += f"//ns:p[re:match(@name,'{p_name}')]"
        else:
            path += "//ns:p"
        return path

    def get_all_descendant_mos(self):
        return [ManagedObject(mo) for mo in self._find_flat_children(self._tree.nsmap[None])]


class XPathElementsList(UserList):
    def __init__(self, *args, used_xpath=None):
        super().__init__(*args)
        self.used_xpath = used_xpath
